import { useQuery, useQueryClient } from "@tanstack/react-query"
import { useId, useState } from "react"
import { Button } from "./ui/button"
import { ApiProblem, api } from "../lib/api"
import { useI18n, type Key } from "../lib/i18n"
import type { HostInfo } from "../lib/types"

const FAILURE_KEYS: Record<string, Key> = {
  "host.identity_invalid": "hostIdentityInvalid",
  "host.identity_revision_conflict": "hostIdentityRevisionConflict",
  "permission.denied": "hostIdentityDenied",
}

type Failure = { code: string; parameters: Record<string, string> }

/**
 * Canonical Host identity control. The Host owns the id and its revision, so the field submits the
 * revision it last read and adopts whatever comes back as canonical instead of the typed value. Relay
 * connections never see the rename control: the entry is loopback-only, so a Relay projection must not
 * offer it and must not read the direct Host locator either.
 */
export function HostIdentityField({ remote }: { remote: boolean }) {
  const { t } = useI18n()
  const queryClient = useQueryClient()
  const hintId = useId()
  const identity = useQuery({ queryKey: ["host"], queryFn: api.host, enabled: !remote })
  // `null` means "follow the canonical identity", so both a successful rename and a conflict re-read
  // land in the field without a second source of truth for the id.
  const [draft, setDraft] = useState<string | null>(null)
  const [status, setStatus] = useState<"idle" | "saving" | "saved">("idle")
  const [failure, setFailure] = useState<Failure | null>(null)
  const canonical = identity.data?.hostId ?? ""
  const value = draft ?? canonical
  const submitted = value.trim()

  async function rename() {
    if (!identity.data || !submitted || submitted === canonical) return
    setStatus("saving")
    setFailure(null)
    try {
      const renamed = await api.renameHost(identity.data.hostIdRevision, submitted)
      queryClient.setQueryData<HostInfo>(["host"], current => current
        ? { ...current, hostId: renamed.hostId, hostIdRevision: renamed.hostIdRevision } : current)
      setDraft(null)
      setStatus("saved")
      await queryClient.invalidateQueries({ queryKey: ["host"] })
    } catch (rejected) {
      // Both transports surface the stable problem code plus its parameters; the Host never sends copy.
      setFailure(rejected instanceof ApiProblem
        ? { code: rejected.problem.code, parameters: rejected.problem.parameters ?? {} }
        : { code: rejected instanceof Error ? rejected.message : String(rejected), parameters: {} })
      setStatus("idle")
      // A stale revision is resolved by the canonical re-read; the typed id stays so the user can retry.
      await identity.refetch()
    }
  }
  ...
}
```

Hmm: `await identity.refetch()` in catch — for the conflict case it re-reads. But for the invalid case it also refetches (harmless, keeps revision fresh). Actually is that desirable? For `host.identity_invalid` a refetch is unnecessary network. Hmm. CredentialSecretField also re-reads on any failure (`try { setRevision(await read()) } catch {}`). So consistent with the precedent. Keep it: it also guarantees the retry uses the current revision for any failure. Good, and matches "revision conflict must re-read the latest canonical identity and let the user retry".

The refetch happens after setFailure, so the alert renders and the form stays. Fine.

